"""Close the complete-source/new-phase-evidence selection after final reports and source selection have stopped writing."""

import argparse
import hashlib
import json
import os
from pathlib import Path
import runpy
import tempfile

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
PHASE = 'result-coordinate-evidence/publication-followup'
PREVIOUS = 'result-coordinate-evidence/compact-page-followup/delivery/selection.json'
SOURCE_SUFFIXES = {'.java', '.py', '.md', '.patch', '.sh', '.jfc'}


def write_new(path, value):
    data = (json.dumps(value, indent=2, sort_keys=True) + '\n').encode()
    descriptor, name = tempfile.mkstemp(prefix='.selection-', dir=path.parent)
    temporary = Path(name)
    try:
        with os.fdopen(descriptor, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.link(temporary, path)
    finally:
        temporary.unlink()
    return hashlib.sha256(data).hexdigest()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo', type=Path, default=ROOT)
    parser.add_argument('--report', action='append', required=True)
    parser.add_argument('--decision', required=True)
    parser.add_argument('--selected-source-record', required=True)
    parser.add_argument('--output', default=PHASE + '/delivery/selection.json')
    parser.add_argument('--audit', default=PHASE + '/delivery/selection-audit.json')
    args = parser.parse_args()
    repo = args.repo.resolve(strict=True)
    api = runpy.run_path(str(repo / 'result-coordinate-evidence/package-coordinate-deliverables.py'))
    relative = lambda value: api['repo_relative'](repo, value)
    output, audit = relative(args.output), relative(args.audit)
    assert output != audit and not (repo / output).exists() and not (repo / audit).exists()
    previous = json.loads((repo / PREVIOUS).read_text())
    derivation = json.loads((repo / PHASE / 'delivery/delta-helper-derivation.json').read_text())
    assert derivation['originalHelpersMatchPriorDeliveredSource'] and derivation['previousSelection'] == PREVIOUS
    assert hashlib.sha256((repo / PREVIOUS).read_bytes()).hexdigest() == derivation['previousSelectionSha256']
    source = set(previous['source_include'])
    for path in (repo / PHASE).rglob('*'):
        if path.is_file() and path.suffix.lower() in SOURCE_SUFFIXES:
            rel = path.relative_to(repo).as_posix()
            assert not path.is_symlink(), rel
            if not api['exclusion'](rel):
                source.add(rel)
    reports = set(previous.get('reports', [])) | {relative(value) for value in args.report}
    source |= reports | {relative(args.decision), relative(args.selected_source_record)}
    extra = {
        'result-coordinate-evidence/materializer-followup/runtime_identity.py',
        'result-coordinate-evidence/materializer-followup/comparison_runtime_io.py',
        'result-coordinate-evidence/materializer-followup/bundle-comparison-runtime.py',
        'result-coordinate-evidence/final-validation/benchmark-source-hashes.json',
        'result-coordinate-evidence/transport-comparison/classpath-manifest.json',
        'result-coordinate-evidence/root-qualified-launcher/classpath.txt',
        PHASE + '/delivery/delta-helper-derivation.json',
        'result-coordinate-evidence/compact-page-followup/delivery/build-turn-delta.py',
    }
    source |= extra
    for rel in source:
        assert (repo / rel).is_file() and not (repo / rel).is_symlink(), rel
    candidates, omissions = api['collect_evidence'](repo, {PHASE}, source, 2 * 1024 * 1024)
    # No partial store copies are useful: the fixtures regenerate their stores.
    store_files = sorted(rel for rel in candidates if 'store' in Path(rel).parts or 'stores' in Path(rel).parts)
    for rel in store_files:
        candidates.pop(rel)
    source |= {output, audit}
    evidence = set(candidates) | source
    selection = {'source_include': sorted(source), 'evidence_roots': [],
                 'evidence_include': sorted(evidence), 'reports': sorted(reports)}
    selection_bytes = (json.dumps(selection, indent=2, sort_keys=True) + '\n').encode()
    record = {'format': 1, 'previousSourceSelection': PREVIOUS,
              'newEvidenceScope': PHASE, 'selection': output,
              'selectionSha256': hashlib.sha256(selection_bytes).hexdigest(),
              'selectedTaskSources': len(source), 'selectedEvidenceFiles': len(evidence),
              'allNewPhaseJavaPythonSourcesSelected': True,
              'historicalEvidenceArchivesRemainSeparateAndPreserved': True,
              'storeMetadataOmitted': store_files, 'standardExclusions': omissions,
              'decisionRecord': relative(args.decision),
              'selectedSourceRecord': relative(args.selected_source_record),
              'binaryEvidencePreservedInRuntime': [],
              'condition': 'Closed inventory after all source/evidence/report writers stop. No archive/build/Java created by this selection step.'}
    write_new(repo / audit, record)
    write_new(repo / output, selection)
    print(json.dumps({'selection': output, 'selectedTaskSources': len(source),
                      'selectedEvidenceFiles': len(evidence), 'javaExecuted': False}, indent=2))


if __name__ == '__main__':
    main()
